  if (config) {
    const crumbs = [config.parent.label]
    const navMatch = findNavItem(config.navigation, href)

    if (navMatch) {
      if (navMatch.groupLabel) crumbs.push(navMatch.groupLabel)
      crumbs.push(navMatch.itemLabel)
